cat > bot.mjs <<'EOF'
// Marketing send gate: at most DAILY_CAP marketing messages per user per local day, all channels together.
// State lives in STATE_DIR (read on every call) so every worker process shares it and it survives restarts.

const DAILY_CAP = 2;
const CHANNELS = new Set(["sms", "email", "push"]);

export async function reserve({ userId, timeZone, channel, now }) {
  if (typeof userId !== "string" || userId === "") return { allowed: false, rule: "invalid-user" };
  if (!CHANNELS.has(channel)) return { allowed: false, rule: "invalid-channel" };
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) return { allowed: false, rule: "invalid-time" };
  if (!gkZoneOk(timeZone)) return { allowed: false, rule: "invalid-timezone" };
  const dir = process.env.STATE_DIR;
  if (!dir) return { allowed: false, rule: "no-state-dir" };

  const day = gkDayKey(now.getTime(), timeZone);
  const { ok } = gkCount(dir, `marketing-daily:${userId}:${day}`, DAILY_CAP);
  return ok ? { allowed: true, rule: "" } : { allowed: false, rule: "daily-cap" };
}
EOF
